def s_rt1b(r, c, g):
    comp = [[-1] * c for _ in range(r)]; info = []
    for i in range(r):
        for j in range(c):
            if g[i][j] != '#' and comp[i][j] == -1:
                cid = len(info); w = 0; e = 0
                q = deque([(i, j)]); comp[i][j] = cid
                while q:
                    a, b = q.popleft()
                    w += g[a][b] == 'W'; e += g[a][b] == 'E'
                    for di, dj in D4:
                        x, y = a + di, b + dj
                        if 0 <= x < r and 0 <= y < c and g[x][y] != '#' and comp[x][y] == -1:
                            comp[x][y] = cid; q.append((x, y))
                info.append((w, e))
    zones = sum(1 for w, e in info if w > 0 and e == 0)
    trapped = sum(w for w, e in info if w > 0 and e == 0)
    dist = bfs(g, r, c, cells(g, r, c, 'E'), D4, lambda ch: ch != '#')
    ds = [dist[i][j] for (i, j) in cells(g, r, c, 'W') if dist[i][j] >= 0]
    return f"{zones} {trapped} {min(ds) if ds else -1}"

