from collections import deque
import heapq
def s_rt2a(n, cl, trips):
    ev = []
    for s, e in trips:
        ev.append((s, 1)); ev.append((e + cl, -1))
    ev.sort(key=lambda x: (x[0], x[1]))   # free (-1) before take (+1) at the same minute
    cur = best = 0
    for _, d in ev:
        cur += d; best = max(best, cur)
    return str(best)

