from collections import deque
import heapq
def s_rt2b(n, T, L, ws):
    ws = sorted(ws); gaps = []; prev = 0
    for l, r in ws:
        if l > prev: gaps.append(l - prev)
        prev = max(prev, r)
    if T > prev: gaps.append(T - prev)
    return f"{max(gaps) if gaps else 0} {sum(1 for g in gaps if g >= L)}"

